<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { supabase } from '@/lib/supabase'

type Setting = { id:string; setting_key:string; setting_value:unknown; description:string|null; updated_at:string }
const rows=ref<Setting[]>([]),loading=ref(false),saving=ref(false),error=ref(''),search=ref('')
const editing=ref<Setting|null>(null),showForm=ref(false),settingKey=ref(''),settingValue=ref(''),description=ref('')
const filtered=computed(()=>{const q=search.value.trim().toLowerCase();return q?rows.value.filter(r=>[r.setting_key,r.description??'',displayValue(r.setting_value)].some(v=>v.toLowerCase().includes(q))):rows.value})
function displayValue(value:unknown){return typeof value==='string'?value:JSON.stringify(value)}
function openForm(row?:Setting){editing.value=row??null;settingKey.value=row?.setting_key??'';settingValue.value=row?displayValue(row.setting_value):'';description.value=row?.description??'';error.value='';showForm.value=true}
function closeForm(){showForm.value=false;editing.value=null}
async function load(){loading.value=true;error.value='';try{const {data,error:e}=await supabase.from('business_settings').select('id,setting_key,setting_value,description,updated_at').order('setting_key');if(e)throw e;rows.value=(data??[]) as Setting[]}catch(e:any){error.value=e.message??'Unable to load settings'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{const payload={setting_key:settingKey.value.trim(),setting_value:settingValue.value,description:description.value.trim()||null,updated_at:new Date().toISOString()};if(!payload.setting_key)throw new Error('Setting name is required.');const result=editing.value?await supabase.from('business_settings').update(payload).eq('id',editing.value.id):await supabase.from('business_settings').insert(payload);if(result.error)throw result.error;closeForm();await load()}catch(e:any){error.value=e.message??'Unable to save setting'}finally{saving.value=false}}
async function remove(row:Setting){if(!confirm('Delete setting “'+row.setting_key+'”?'))return;const {error:e}=await supabase.from('business_settings').delete().eq('id',row.id);if(e)error.value=e.message;else await load()}
onMounted(load)
</script>
<template><section class="page-wrap"><div class="page-heading"><div><h1>System settings</h1><p>Configure the shop environment. This area is reserved for the System Super Admin.</p></div><button class="btn primary" @click="openForm">＋ Add setting</button></div>
<div class="toolbar"><input v-model="search" class="control search" placeholder="Search settings…"><button class="btn" @click="load">Refresh</button><span class="muted">{{filtered.length}} settings</span></div>
<p v-if="error" class="alert">{{error}}</p><div v-if="loading" class="empty">Loading settings…</div><div v-else class="table-scroll"><table><thead><tr><th>Setting name</th><th>Value</th><th>Description</th><th>Last updated</th><th>Actions</th></tr></thead><tbody><tr v-for="row in filtered" :key="row.id"><td>{{row.setting_key}}</td><td class="value-cell">{{displayValue(row.setting_value)}}</td><td>{{row.description||'—'}}</td><td>{{new Date(row.updated_at).toLocaleString()}}</td><td class="actions"><button class="link" @click="openForm(row)">Edit</button><button class="link danger" @click="remove(row)">Delete</button></td></tr><tr v-if="!filtered.length"><td colspan="5" class="empty">No settings have been added yet.</td></tr></tbody></table></div>
<div v-if="showForm" class="modal-backdrop" @click.self="closeForm"><form class="modal" @submit.prevent="save"><div class="page-heading"><h2>{{editing?'Edit setting':'Add setting'}}</h2><button type="button" class="link" @click="closeForm">Close</button></div><label>Setting name<input v-model="settingKey" class="control" required maxlength="120" :disabled="!!editing" placeholder="e.g. shop_name"></label><label>Setting value<input v-model="settingValue" class="control" required placeholder="Enter a value"></label><label>Description (optional)<textarea v-model="description" class="control" rows="2" placeholder="What does this setting control?"></textarea></label><p v-if="error" class="alert">{{error}}</p><div class="modal-actions"><button type="button" class="btn" @click="closeForm">Cancel</button><button class="btn primary" :disabled="saving">{{saving?'Saving…':'Save setting'}}</button></div></form></div></section></template>